FROM rocker/shiny:4.4.0

ENV SHINY_APP_DIR=/srv/shiny-server/app

USER root

RUN mkdir -p ${SHINY_APP_DIR}

COPY . ${SHINY_APP_DIR}

WORKDIR ${SHINY_APP_DIR}

RUN Rscript install_packages.R

RUN chown -R shiny:shiny ${SHINY_APP_DIR}

USER shiny

VOLUME ["${SHINY_APP_DIR}/data"]

EXPOSE 3838

CMD ["R", "-e", "options(shiny.port=3838, shiny.host='0.0.0.0'); shiny::runApp('.')"]

# Script para instalar los paquetes necesarios para la aplicación Shiny

# Lista de paquetes requeridos
required_packages <- c(
  "shiny",
  "bslib",
  "dplyr",
  "DT",
  "leaflet"
)

# Función para verificar e instalar paquetes
install_if_missing <- function(package) {
  if (!require(package, character.only = TRUE, quietly = TRUE)) {
    cat(paste0("Instalando ", package, "...\n"))
    install.packages(package, dependencies = TRUE)
  } else {
    cat(paste0(package, " ya está instalado.\n"))
  }
}

# Instalar paquetes faltantes
cat("Verificando e instalando paquetes necesarios...\n\n")
invisible(sapply(required_packages, install_if_missing))

cat("\n¡Instalación completada!\n")
cat("Para ejecutar la aplicación, usa: shiny::runApp()\n")

// JavaScript para manejo de chips de búsqueda

$(document).ready(function() {
  // Array para almacenar los términos de búsqueda
  let searchTerms = [];
  
  // Función para renderizar chips
  function renderChips() {
    const container = $('#chips-container');
    container.empty();
    
    if (searchTerms.length === 0) {
      container.append('<span class="chips-empty">Escribe términos de búsqueda y presiona Enter o Espacio</span>');
    } else {
      searchTerms.forEach(function(term, index) {
        const chip = $('<div class="search-chip">')
          .append($('<span>').text(term))
          .append($('<button class="chip-remove" data-index="' + index + '">×</button>'));
        container.append(chip);
      });
    }
    
    // Enviar términos al servidor
    Shiny.setInputValue('search_chips', searchTerms, {priority: 'event'});
  }
  
  // Función para agregar término
  function addTerm(term) {
    term = term.trim();
    if (term !== '' && !searchTerms.includes(term)) {
      searchTerms.push(term);
      renderChips();
    }
  }
  
  // Evento al presionar teclas en el input
  $('#search_input').on('keydown', function(e) {
    const value = $(this).val().trim();
    
    // Enter (13) o Espacio (32)
    if ((e.keyCode === 13 || e.keyCode === 32) && value !== '') {
      e.preventDefault();
      addTerm(value);
      $(this).val('');
    }
    
    // Backspace en input vacío: eliminar último chip
    if (e.keyCode === 8 && value === '' && searchTerms.length > 0) {
      e.preventDefault();
      searchTerms.pop();
      renderChips();
    }
  });
  
  // Evento para eliminar chip individual
  $(document).on('click', '.chip-remove', function() {
    const index = parseInt($(this).data('index'));
    searchTerms.splice(index, 1);
    renderChips();
  });
  
  // Botón limpiar
  $('#clear_search').on('click', function() {
    searchTerms = [];
    $('#search_input').val('');
    renderChips();
  });
  
  // Inicializar contenedor vacío
  renderChips();
  
  // Listener para cuando Shiny resetea la búsqueda
  Shiny.addCustomMessageHandler('reset_chips', function(message) {
    searchTerms = [];
    $('#search_input').val('');
    renderChips();
  });
});

/* Custom CSS para la aplicación de búsqueda */

/* Contenedor de chips */
.chips-container {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
  min-height: 40px;
  padding: 8px;
  background-color: #f8f9fa;
  border-radius: 8px;
  border: 1px solid #dee2e6;
}

/* Estilo de cada chip */
.search-chip {
  display: inline-flex;
  align-items: center;
  background-color: #0d6efd;
  color: white;
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 14px;
  font-weight: 500;
  animation: chipAppear 0.2s ease-out;
}

@keyframes chipAppear {
  from {
    opacity: 0;
    transform: scale(0.8);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* Botón X en el chip */
.chip-remove {
  margin-left: 8px;
  background: none;
  border: none;
  color: white;
  cursor: pointer;
  font-size: 16px;
  font-weight: bold;
  padding: 0;
  width: 18px;
  height: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  transition: background-color 0.2s;
}

.chip-remove:hover {
  background-color: rgba(255, 255, 255, 0.2);
}

/* Mensaje cuando no hay chips */
.chips-empty {
  color: #6c757d;
  font-style: italic;
  font-size: 14px;
  padding: 4px;
}

/* Estilo del campo de búsqueda */
#search_input {
  font-size: 16px;
  padding: 12px;
  border-radius: 8px;
  border: 2px solid #dee2e6;
  transition: border-color 0.2s;
}

#search_input:focus {
  border-color: #0d6efd;
  outline: none;
  box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.25);
}

/* Botones de acción */
.action-buttons {
  display: flex;
  gap: 10px;
  margin-top: 15px;
}

/* Card de resultados */
.results-card {
  margin-top: 20px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

/* Mapa */
#map {
  height: 500px;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

/* Tabla de resultados */
.dataTable {
  font-size: 14px;
}

.dataTables_wrapper {
  padding: 15px;
}

/* Badge de contador */
.results-badge {
  background-color: #0d6efd;
  color: white;
  padding: 4px 12px;
  border-radius: 12px;
  font-size: 13px;
  font-weight: 600;
  margin-left: 10px;
}

/* Ayuda contextual */
.search-help {
  font-size: 13px;
  color: #6c757d;
  margin-top: 8px;
  font-style: italic;
}

/* Responsive adjustments */
@media (max-width: 768px) {
  .chips-container {
    min-height: 50px;
  }
  
  .search-chip {
    font-size: 13px;
    padding: 5px 10px;
  }
}
